"""Runtime used by Python cases generated by MiiX Studio."""
import inspect
import json
import os
import re
import subprocess
import time
import xml.etree.ElementTree as ET


def adb_path():
    return os.environ.get("MIIX_ADB", "adb")


def connected_devices():
    result = subprocess.run([adb_path(), "devices"], capture_output=True, timeout=10)
    if result.returncode:
        message = result.stderr.decode("utf-8", "replace").strip()
        raise RuntimeError(message or "无法读取 adb devices")
    devices = []
    for line in result.stdout.decode("utf-8", "replace").splitlines()[1:]:
        parts = line.split()
        if len(parts) >= 2 and parts[1] == "device":
            devices.append(parts[0])
    return devices


def resolve_serial(serial=None):
    serial = serial or os.environ.get("MIIX_SERIAL")
    if serial:
        return serial
    devices = connected_devices()
    if len(devices) == 1:
        return devices[0]
    if not devices:
        raise ValueError("没有发现在线 Android 设备。请先执行 adb devices，或在 PyCharm 运行配置里设置 MIIX_SERIAL。")
    raise ValueError("发现多台 Android 设备，请在 PyCharm 运行配置里设置环境变量 MIIX_SERIAL，或添加参数 --serial <设备ID>。在线设备：" + ", ".join(devices))


def _adb(serial, *args, timeout=20):
    result = subprocess.run([adb_path(), "-s", serial, *map(str, args)], capture_output=True, timeout=timeout)
    if result.returncode:
        message = result.stderr.decode("utf-8", "replace").strip()
        raise RuntimeError(message or "ADB 操作失败")
    return result.stdout.decode("utf-8", "replace")


def _adb_bytes(serial, *args, timeout=20):
    result = subprocess.run([adb_path(), "-s", serial, *map(str, args)], capture_output=True, timeout=timeout)
    if result.returncode:
        message = result.stderr.decode("utf-8", "replace").strip()
        raise RuntimeError(message or "ADB 操作失败")
    return result.stdout


class Element:
    def __init__(self, device, selector):
        self.device, self.selector = device, selector

    def _node(self):
        tree = self.device._tree()
        aliases = {"resource_id": "resource-id", "description": "content-desc", "text": "text"}
        if "parent_child" in self.selector:
            raise RuntimeError("父子定位暂不能在 Python 执行器中解析，请重新抓取为 Resource ID 或 XPath")
        matches = []
        for node in tree.iter("node"):
            if all(node.get(aliases.get(key, key)) == str(value) for key, value in self.selector.items() if key != "xpath"):
                matches.append(node)
        if "xpath" in self.selector:
            value = self.selector["xpath"]
            match = re.search(r"@(?:resource-id|text|content-desc)=(?:\"([^\"]*)\"|'([^']*)')", value)
            if match:
                needle = match.group(1) or match.group(2) or ""
                attr = "resource-id" if "resource-id" in value else "content-desc" if "content-desc" in value else "text"
                matches = [node for node in tree.iter("node") if node.get(attr) == needle]
        if not matches:
            raise LookupError("未找到控件：" + json.dumps(self.selector, ensure_ascii=False))
        if len(matches) > 1:
            raise LookupError("控件定位不唯一：匹配到 %d 个控件" % len(matches))
        return matches[0]

    @staticmethod
    def _center(node):
        values = [int(v) for v in re.findall(r"-?\d+", node.get("bounds", ""))]
        if len(values) != 4:
            raise RuntimeError("控件没有有效坐标")
        return (values[0] + values[2]) // 2, (values[1] + values[3]) // 2

    def click(self, timeout=10):
        return self.device._step(lambda: _adb(self.device.serial, "shell", "input", "tap", *self._center(self._node()), timeout=timeout))

    def double_click(self, timeout=10):
        def action():
            x, y = self._center(self._node())
            _adb(self.device.serial, "shell", "input", "tap", x, y, timeout=timeout)
            time.sleep(0.12)
            _adb(self.device.serial, "shell", "input", "tap", x, y, timeout=timeout)
        return self.device._step(action)

    def long_press(self, timeout=10, duration=800):
        def action():
            x, y = self._center(self._node())
            _adb(self.device.serial, "shell", "input", "swipe", x, y, x, y, duration, timeout=timeout)
        return self.device._step(action)

    def clear(self, timeout=10):
        def action():
            _adb(self.device.serial, "shell", "input", "tap", *self._center(self._node()), timeout=timeout)
            _adb(self.device.serial, "shell", "input", "keyevent", "KEYCODE_MOVE_END", timeout=timeout)
            for _ in range(80):
                _adb(self.device.serial, "shell", "input", "keyevent", "KEYCODE_DEL", timeout=timeout)
        return self.device._step(action)

    def input(self, value, timeout=10):
        def action():
            _adb(self.device.serial, "shell", "input", "tap", *self._center(self._node()), timeout=timeout)
            if not isinstance(value, str) or re.search(r"[^\x20-\x7e]", value):
                raise ValueError("当前 Python ADB 输入支持英文；中文输入需手机 Agent")
            _adb(self.device.serial, "shell", "input", "text", value.replace(" ", "%s"), timeout=timeout)
        return self.device._step(action)

    def check(self, type="exists", expected=None, timeout=10, stable_for=0, failure="stop"):
        def action():
            deadline = time.monotonic() + timeout
            while True:
                try:
                    node = self._node()
                    exists = True
                except LookupError:
                    node, exists = None, False
                actual = exists
                passed = exists if type in ("exists", "visible") else not exists if type == "not_exists" else False
                if exists and type in ("text_equals", "text_contains"):
                    actual = node.get("text", "")
                    passed = actual == expected if type == "text_equals" else str(expected) in actual
                elif exists and type in ("enabled", "disabled", "clickable", "checked", "selected"):
                    attr = "enabled" if type == "disabled" else type
                    actual = node.get(attr) == "true"
                    passed = (not actual) if type == "disabled" else actual
                if passed:
                    if stable_for:
                        time.sleep(stable_for / 1000)
                    return actual
                if time.monotonic() >= deadline:
                    raise AssertionError("检查点未通过：预期 %r，实际 %r" % (expected, actual))
                time.sleep(.25)
        return self.device._step(action, continue_on_error=failure == "continue")


class Device:
    def __init__(self, serial):
        if not serial:
            raise ValueError("未选择 Android 设备")
        self.serial, self.results = resolve_serial(serial), []

    def __call__(self, **selector):
        return Element(self, selector)

    def _tree(self):
        text = _adb(self.serial, "exec-out", "uiautomator", "dump", "/dev/tty")
        start = text.find("<?xml")
        end = text.rfind("</hierarchy>")
        if start < 0 or end < start:
            raise RuntimeError("设备未返回有效控件树")
        return ET.fromstring(text[start:end + len("</hierarchy>")])

    def _step(self, action, continue_on_error=False):
        line = inspect.currentframe().f_back.f_back.f_lineno
        result = {"index": len(self.results) + 1, "line": line, "status": "running"}
        started = time.monotonic()
        try:
            result["actual"] = action()
            result["status"] = "passed"
        except Exception as error:
            result.update(status="failed", error=str(error))
        result["durationMs"] = round((time.monotonic() - started) * 1000)
        self.results.append(result)
        if result["status"] != "passed" and not continue_on_error:
            raise RuntimeError(result["error"])
        return result.get("actual")

    def sleep(self, seconds):
        return self._step(lambda: time.sleep(float(seconds)))

    def swipe(self, x, y, to_x, to_y, duration=300):
        return self._step(lambda: _adb(self.serial, "shell", "input", "swipe", x, y, to_x, to_y, duration))

    def key(self, code):
        code = int(code)
        allowed = {3, 4, 24, 25, 26, 187}
        if code not in allowed:
            raise ValueError("暂不支持的系统按键：%s" % code)
        return self._step(lambda: _adb(self.serial, "shell", "input", "keyevent", code))

    def launch(self, package):
        if not package or not re.match(r"^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$", str(package)):
            raise ValueError("应用包名格式不正确")
        return self._step(lambda: _adb(self.serial, "shell", "monkey", "-p", package, "-c", "android.intent.category.LAUNCHER", "1", timeout=30))

    def screenshot(self):
        def action():
            report_dir = os.environ.get("MIIX_REPORT_DIR")
            data = _adb_bytes(self.serial, "exec-out", "screencap", "-p", timeout=20)
            if report_dir:
                os.makedirs(report_dir, exist_ok=True)
                name = "manual-screenshot-%03d.png" % (len([x for x in os.listdir(report_dir) if x.startswith("manual-screenshot-")]) + 1)
                path = os.path.join(report_dir, name)
                with open(path, "wb") as handle:
                    handle.write(data)
                return path
            return "screenshot captured"
        return self._step(action)
